contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // depositAmt: amount to deposit into c
    // collectAmt: amount to attempt to collect
    // minSum: value to set as MinSum before collecting
    function run(uint depositAmt, uint collectAmt, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // Set MinSum before initialization (allowed)
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;

        // Deposit depositAmt into c as this contract (top-level state-changing call)
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Read observable state before Collect
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Attempt to Collect collectAmt and record whether it reverted
        bool collectReverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        // Read observable state after Collect
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule: if Collect succeeded then the decrease in the contract's ETH balance
        // equals the decrease in the caller's recorded balance.
        // i.e., (beforeContractBal - afterContractBal) == (beforeRecorded - afterRecorded)
        // To avoid underflow in subtraction inside assert, express equality as sums:
        // beforeContractBal + afterRecorded == afterContractBal + beforeRecorded
        assert(collectReverted || (beforeContractBal + afterRecorded == afterContractBal + beforeRecorded));
    }

    receive() external payable {}
}

